INSERT INTO `announcements` (`id`, `title`, `content`, `author_id`, `author_name`, `author_role`, `target_audience`, `created_at`) VALUES
(1, 'Welcome to School Year 2025-2026!', 'We are excited to welcome all students back to school. Please check your schedules and attend classes regularly.', 1, 'Juan Dela Cruz', 'admin', 'all', '2026-05-21 02:40:48'),
(2, 'First Quarter Examination Schedule', 'The first quarterly examination will be held on June 15-20, 2026. Please review your lessons and prepare well.', 1, 'Juan Dela Cruz', 'admin', 'students', '2026-05-21 02:40:48'),
(3, 'Teacher Development Program', 'All teachers are required to attend the professional development seminar on June 10, 2026 at the school auditorium.', 1, 'Juan Dela Cruz', 'admin', 'teachers', '2026-05-21 02:40:48');
